const cm = d.comments ?? {};
const dmc = d.dm ?? {}; // FS-DM-var
const dmSo = d.dm ?? {};
// FS-DM-var2：主动私信的点选名单（候选 = 上次拉到的互关名单；选中 = 存进配置的 targets）
const [dmCands, setDmCands] = react.useState(null);
const [dmPicked, setDmPicked] = react.useState(null);
const [dmErrHidden, setDmErrHidden] = react.useState(false);
const [dmTypeDraft, setDmTypeDraft] = react.useState("");
const dmPickedList = dmPicked ?? (Array.isArray(dmc.targets) ? dmc.targets : []);
const dmCandList = dmCands ?? (Array.isArray(dmSo.mutualList) ? dmSo.mutualList : []);
const dmIsPicked = (x) => dmPickedList.some((p) => String(p?.name ?? "") === String(x?.name ?? ""));
const dmToggle = (x) => {
	const has = dmIsPicked(x);
	const nextList = has
		? dmPickedList.filter((p) => String(p?.name ?? "") !== String(x?.name ?? ""))
		: [...dmPickedList, { name: String(x?.name ?? ""), uid: String(x?.uid ?? ""), shareType: "" }];
	setDmPicked(nextList);
	save({ dm: { targets: nextList } });
};
// FS-DM-TYPE：每个已选的人单独选定「只分享哪几类视频」（可多选；空 = 跟默认；* = 所有类型）
const DM_TYPE_ALL = "*";
const dmTypes = Array.isArray(dmSo.shareTypeNames) && dmSo.shareTypeNames.length > 0
	? dmSo.shareTypeNames
	: ["搞笑", "游戏", "美食", "宠物", "旅行", "音乐舞蹈", "颜值穿搭", "剧情影视", "数码科技", "情感", "日常", "学习", "运动"];
const dmTypeList = (p) => String(p?.shareType ?? "").split(/[，,、\s]+/).map((s) => s.trim()).filter((s) => s !== "" && s !== DM_TYPE_ALL);
// FS-DM-TYPE-default：默认分享哪几类（没单独指定的人按这个）
const dmDefaultList = String(dmSo.defaultShareTypes ?? "").split(/[，,、\s]+/).map((s) => s.trim()).filter((s) => s !== "");
// FS-DM-TYPE-ALL：内置那 13 类（不在这里面的 = 你自己加的类型，可以删掉）
const DM_BUILTIN_TYPES = ["搞笑", "游戏", "美食", "宠物", "旅行", "音乐舞蹈", "颜值穿搭", "剧情影视", "数码科技", "情感", "日常", "学习", "运动"];
const dmCustomTypes = dmTypes.filter((t) => !DM_BUILTIN_TYPES.includes(t));
// FS-DM-TYPE-ALL：设置页拿到的是 [{name, words}]，保存要的是 { 类型名: "关键词,关键词" }
const dmTypeMap = () => {
	const out = {};
	for (const t of Array.isArray(dmSo.shareTypes) ? dmSo.shareTypes : []) {
		const name = String(t?.name ?? "").trim();
		if (name === "") continue;
		out[name] = (Array.isArray(t?.words) ? t.words : []).join(",");
	}
	return out;
};
const dmSetDefaultType = (type) => {
	const list = dmDefaultList.includes(type) ? dmDefaultList.filter((t) => t !== type) : [...dmDefaultList, type];
	save({ dm: { defaultShareTypes: list.join(",") } });
};
const dmSetType = (name, type) => {
	const next = dmPickedList.map((p) => {
		if (String(p?.name ?? "") !== String(name ?? "")) return p;
		const cur = dmTypeList(p);
		const list = cur.includes(type) ? cur.filter((t) => t !== type) : [...cur, type];
		return { ...p, shareType: list.join(",") };
	});
	setDmPicked(next);
	save({ dm: { targets: next } });
};
// FS-DM-TYPE-ALL：把某个人的类型置成固定档（"" = 跟默认，"*" = 所有类型）
const dmSetTypeMode = (name, mode) => {
	const next = dmPickedList.map((p) => (String(p?.name ?? "") === String(name ?? "") ? { ...p, shareType: mode } : p));
	setDmPicked(next);
	save({ dm: { targets: next } });
};
// FS-DM-TYPE-ALL：自己写一个类型（「类型名=关键词,关键词」；只写名字就拿名字本身当关键词）
const dmAddType = () => {
	const raw = String(dmTypeDraft ?? "").trim();
	if (raw === "") return;
	const cut = raw.search(/[=＝:：]/);
	const name = (cut >= 0 ? raw.slice(0, cut) : raw).trim().slice(0, 20);
	const words = cut >= 0 ? raw.slice(cut + 1).trim().slice(0, 200) : name;
	if (name === "" || /[，,、]/.test(name)) { notify("类型名里别带逗号，写成「类型名=关键词,关键词」"); return; }
	if (words.replace(/[，,、\s]/g, "") === "") { notify("关键词不能空着"); return; }
	const map = dmTypeMap();
	map[name] = words;
	setDmTypeDraft("");
	save({ dm: { shareTypes: map } });
};
// FS-DM-TYPE-ALL：删掉自己加的类型（内置那 13 类删不掉）
const dmDropType = (name) => {
	const map = dmTypeMap();
	delete map[name];
	const next = dmPickedList.map((p) => ({ ...p, shareType: dmTypeList(p).filter((t) => t !== name).join(",") }));
	setDmPicked(next);
	save({ dm: { shareTypes: map, targets: next } });
};

