/**
 * [FS-DM-SESSION] 抖音主动私信：让「抖音·某某」这个会话里的她自己写那句话，再由宿主把这一轮回给抖音。
 *
 * 为什么绕这一圈：以前主动私信是插件直接在页面上点「发送」，那条消息只进了抖音、没进 DSH 的会话，
 * 所以 DSH 的「抖音对话」里只有对方发来的，没有她发出去的 —— 往来记录缺一半（主人实测发现的）。
 * 走会话以后，DSH 里写的话和真正发出去的私信是同一句，界面里也是完整的一轮。
 *
 * @returns {Promise<{ok: boolean, sent: boolean, text: string, error?: string}>}
 */
async triggerDouyinProactive(name, hint) {
	const nickname = String(name ?? '').trim();
	if (nickname === '') return { ok: false, sent: false, text: '', error: '没给要发给谁' };
	if (this.douyin === null || this.douyin?.host?.running !== true) {
		return { ok: false, sent: false, text: '', error: '抖音浏览器没在运行' };
	}
	const channelId = `douyin:${nickname}`;
	const chat = { channelId, chatType: 'private', targetId: nickname, title: '' };
	const agent = await this.ensureSession(chat);
	this.applyChatModelFor(agent, channelId);
	const person = findPersonByDouyin(this.db, nickname);
	this.turnMood ??= new Map();
	this.turnMood.set(agent.id, this.moodOf(person));
	this.soul.beginTurn(agent.id, {
		channel: sessionChannelOf(channelId),
		channelId,
		replyChannel: channelId,
		speakers: person !== null ? [{ person, userId: nickname, displayName: person.display_name, text: hint }] : [],
		proactive: true,
		workspacePath: this.bound.get(agent.id)?.workspace_path ?? this.workspacePath()
	});
	const st = this.turnState(agent.id);
	st.channelId = channelId;
	st.douyinOutbound = true; // 只这一轮允许真的发到抖音（见 sendReply）
	st.douyinText = '';
	st.douyinSent = false;
	st.douyinSilent = false;
	this.interjectTurns.delete(agent.id);
	this.note('proactive', { channelId, reason: sanitizeUserText(hint).slice(0, 60) });
	const msgId = randomUUID();
	const done = new Promise((resolveDone) => {
		const timer = setTimeout(() => {
			this.waiters.delete(msgId);
			resolveDone(false);
		}, PROACTIVE_TURN_TIMEOUT_MS);
		timer.unref?.();
		this.waiters.set(msgId, { resolve: resolveDone, timer });
	});
	try {
		await agent.followup({
			id: msgId,
			role: 'user',
			content: [{
				type: 'text',
				text: `【主动开口】${this.soul.nowLabel()}，你刚在抖音私信里给她分享了一条你自己的视频。` +
					`视频是：${sanitizeUserText(hint)}。` +
					'接着写一句跟在卡片后面的话：就着这条视频本身说，不要描述画面，' +
					'别提"系统""提醒任务""主动开口"这些字眼，像平时聊天一样自然，一句话就够。'
			}],
			source: { kind: SOURCE_PROACTIVE, channelId, reason: String(hint), origin: 'douyin-dm' }
		});
	} catch (error) {
		const w = this.waiters.get(msgId);
		if (w !== undefined) { clearTimeout(w.timer); this.waiters.delete(msgId); }
		throw error;
	}
	const ok = await done;
	const sent = st.douyinSent === true;
	const silent = st.douyinSilent === true; // 她这轮选择不说话：不算失败，别让上层再补写
	return { ok, sent, silent, text: String(st.douyinText ?? ''), ...(ok ? {} : { error: '模型没写完，这一轮没发出去' }) };
}

/** [FS-DM-SESSION] 真的把一段话发到抖音私信（点页面，回读验证）。 */
async sendDouyinDm(row, text) {
	const ch = this.douyin;
	if (ch === null || typeof ch?.send !== 'function') return { ok: false, delivered: false, parts: [], error: '抖音通道没接上' };
	const name = String(splitChannelId(row.channel_id)[1] ?? '');
	if (name === '') return { ok: false, delivered: false, parts: [], error: '不知道要发给谁' };
	const parts = String(text ?? '').split(/\n{2,}/).map((s) => s.trim()).filter((s) => s !== '').map((s) => ({ type: 'text', text: s }));
	if (parts.length === 0) return { ok: true, delivered: true, parts: [] };
	try {
		const r = await ch.send(name, parts);
		return r !== null && typeof r === 'object' ? r : { ok: false, delivered: false, parts: [], error: '抖音没返回结果' };
	} catch (error) {
		return { ok: false, delivered: false, parts: [], error: String(error instanceof Error ? error.message : error) };
	}
}

